-- Modify "orders" table
ALTER TABLE "orders" DROP CONSTRAINT "orders_status_valid", ADD CONSTRAINT "orders_status_valid" CHECK ((status)::text = ANY ((ARRAY['pending_payment'::character varying, 'awaiting_procurement'::character varying, 'confirmed'::character varying, 'processing'::character varying, 'shipped'::character varying, 'delivered'::character varying, 'completed'::character varying, 'payment_expired'::character varying, 'cancelled'::character varying])::text[])), ADD CONSTRAINT "orders_origin_valid" CHECK ((((order_type)::text = 'standard'::text) AND (checkout_id IS NOT NULL) AND (cart_id IS NOT NULL)) OR (((order_type)::text = 'sourcing'::text) AND (checkout_id IS NULL) AND (cart_id IS NULL) AND (customer_id IS NOT NULL))), ADD CONSTRAINT "orders_type_valid" CHECK ((order_type)::text = ANY ((ARRAY['standard'::character varying, 'sourcing'::character varying])::text[])), ALTER COLUMN "checkout_id" DROP NOT NULL, ALTER COLUMN "cart_id" DROP NOT NULL, ADD COLUMN "order_type" character varying(20) NOT NULL DEFAULT 'standard';
-- Create index "idx_orders_type_created" to table: "orders"
CREATE INDEX "idx_orders_type_created" ON "orders" ("order_type", "created_at");
